package dev.veltraph.client.chocolate;

import com.mojang.brigadier.CommandDispatcher;
import com.mojang.brigadier.arguments.*;
import net.fabricmc.fabric.api.client.command.v2.*;
import net.minecraft.network.chat.Component;
import dev.veltraph.client.core.ModuleActivationGuard;
import java.math.BigDecimal;
import java.util.*;
import java.util.function.Consumer;
import static net.fabricmc.fabric.api.client.command.v2.ClientCommands.*;

/** Local inspection/capture/planning commands; selecting is inactive until standard guarded start. */
public final class ChocolateFactoryCommands {
    private ChocolateFactoryCommands() {}
    private static final ThreadLocal<Consumer<String>> menuOutput=new ThreadLocal<>();
    public static int executeInMenu(CommandDispatcher<FabricClientCommandSource> dispatcher,FabricClientCommandSource source,String command,Consumer<String> output) throws com.mojang.brigadier.exceptions.CommandSyntaxException {
        if(command.startsWith("/"))command=command.substring(1);if(!command.equals("vchocolate")&&!command.startsWith("vchocolate "))throw new IllegalArgumentException("Only local vchocolate commands are accepted here");
        var previous=menuOutput.get();menuOutput.set(output);try{return dispatcher.execute(command,source);}finally{if(previous==null)menuOutput.remove();else menuOutput.set(previous);}
    }
    private static void menuFeedback(String text){var output=menuOutput.get();if(output!=null)output.accept(text);}
    private static final class Holder {ChocolateFactoryDraft draft;}
    private static int run(FabricClientCommandSource source,Consumer<Consumer<String>> task){try{task.accept(s->{source.sendFeedback(Component.literal("Chocolate Factory: "+s));menuFeedback(s);});return 1;}catch(RuntimeException error){source.sendError(Component.literal("Chocolate Factory: "+error.getMessage()));menuFeedback(error.getMessage());return 0;}}
    private static BigDecimal decimal(String text){try{var n=new BigDecimal(text);if(n.signum()<0||n.scale()>12||n.precision()>30)throw new IllegalArgumentException("Bounded nonnegative decimal required");return n;}catch(NumberFormatException e){throw new IllegalArgumentException("Exact decimal required; no abbreviations");}}
    public static void register(CommandDispatcher<FabricClientCommandSource> dispatcher,ChocolateFactoryModule module,ModuleActivationGuard guard){
        var holder=new Holder();
        dispatcher.register(literal("vchocolate")
            .executes(c->run(c.getSource(),out->{out.accept(module.diagnostics());out.accept("auto scope; transactions; transaction-resource CHOCOLATE|COINS slot prefix suffix; transaction-output inventorySlot; transaction-select SHOP|HITMAN|MILESTONE slot cumulativeBudget reserve; transaction-confirm; tower-select; prestige-preview maximumObservedWallet; prestige-confirm reset-all; actions; action-reconcile intent applied|not-applied original-scope; state; collection; inspect/show; begin profile slot loreLine; upgrade id kind slot cueLine; field role slot LORE|NAME prefix suffix; delta id amount evidence; save; plan reserve; goal id amount reserve; select ids budget reserve; repeat employee count budget reserve waitSeconds; start; stop; queues; queue-inspect intent original-scope declare-original-account; reconcile intent purchased|not-purchased original-scope declare-original-account");}))
            .then(literal("inspect").executes(c->run(c.getSource(),out->{var o=module.visibleMenu();if(o==null)throw new IllegalArgumentException("Open a native menu first");out.accept("Observed title: "+o.title()+"; revision "+o.revision()+"; cursor "+(o.cursorEmpty()?"empty":"occupied"));for(var r:o.rows().values().stream().sorted(Comparator.comparingInt(ChocolateFactoryObservation.Row::slot)).toList())if(!r.playerInventory()&&r.count()>0)out.accept("slot "+r.slot()+": "+r.itemId()+" / "+r.name());})))
            .then(literal("show").then(argument("slot",IntegerArgumentType.integer(0,255)).executes(c->run(c.getSource(),out->{var o=module.visibleMenu();if(o==null)throw new IllegalArgumentException("Open a native menu first");var r=o.rows().get(IntegerArgumentType.getInteger(c,"slot"));if(r==null)throw new IllegalArgumentException("No native slot");out.accept(r.name()+" ["+r.itemId()+"]");for(int i=0;i<r.lore().size();i++)out.accept("lore "+i+": "+r.lore().get(i));}))))
            .then(literal("auto").then(argument("scope",StringArgumentType.word()).executes(c->run(c.getSource(),out->{module.captureAutomaticProfile(StringArgumentType.getString(c,"scope"));holder.draft=null;out.accept("Captured Factory III/IV grammar selected and bound deliberately to this native player/world/connection session. No named account/profile marker was captured; restart/context replacement requires auto again. Purchases remain explicitly disabled until enabled.");}))))
            .then(literal("state").executes(c->run(c.getSource(),out->{var s=module.capturedState();out.accept("Factory "+s.factoryLevel()+", complete "+s.complete()+", wallet "+s.balance()+", cap "+s.capacity()+", CpS "+s.production()+", earned this prestige "+s.prestigeProgress()+", target "+s.prestigeGoal()+", all-time "+s.allTime());out.accept("Rabbits "+s.rabbitsOwned()+" / barn "+s.rabbitCapacity()+" / collection "+s.collectionTotal());var raw=module.visibleMenu();CapturedChocolateFactoryParser.tower(raw.rows()).ifPresent(t->out.accept("Time Tower "+t.level()+" "+t.status()+", active seconds "+t.activeRemainingSeconds()+", charge seconds "+t.chargeRemainingSeconds()+", charges "+t.charges()+"/"+t.maxCharges()+"; no automatic activation"));out.accept("Chocobit count, upkeep due time/funding and faction choice are not present on this captured III/IV layout");for(var note:s.notes())out.accept(note);})))
            .then(literal("collection").executes(c->run(c.getSource(),out->{var o=module.visibleMenu();if(o==null)throw new IllegalArgumentException("Open an actual Hoppity collection page");var page=CapturedChocolateFactoryParser.collectionPage(o.title(),o.rows()).orElseThrow(()->new IllegalArgumentException("Unrecognized collection layout"));out.accept("Page "+page.page()+"/"+page.totalPages()+"; "+page.coverage());for(var r:page.rabbits())out.accept(r.name()+": "+r.rarity()+" "+r.status()+" "+r.requirements());})))
            .then(literal("begin").then(argument("scope",StringArgumentType.word()).then(argument("slot",IntegerArgumentType.integer(0,255)).then(argument("line",IntegerArgumentType.integer(0,100)).executes(c->run(c.getSource(),out->{holder.draft=new ChocolateFactoryDraft(StringArgumentType.getString(c,"scope"),module.visibleMenu(),IntegerArgumentType.getInteger(c,"slot"),IntegerArgumentType.getInteger(c,"line"));out.accept("Inactive local draft captured; choose exact numeric fields and upgrades");}))))))
            .then(literal("upgrade").then(argument("id",StringArgumentType.word()).then(argument("kind",StringArgumentType.word()).then(argument("slot",IntegerArgumentType.integer(0,255)).then(argument("cueLine",IntegerArgumentType.integer(0,100)).executes(c->run(c.getSource(),out->{draft(holder).upgrade(StringArgumentType.getString(c,"id"),ChocolateFactoryProfile.Kind.valueOf(StringArgumentType.getString(c,"kind").toUpperCase(Locale.ROOT)),module.visibleMenu(),IntegerArgumentType.getInteger(c,"slot"),IntegerArgumentType.getInteger(c,"cueLine"));out.accept("Upgrade identity and exact action cue captured; configure id.level and id.price");})))))))
            .then(literal("field").then(argument("role",StringArgumentType.word()).then(argument("slot",IntegerArgumentType.integer(0,255)).then(argument("source",StringArgumentType.word()).then(argument("prefix",StringArgumentType.string()).then(argument("suffix",StringArgumentType.string()).executes(c->run(c.getSource(),out->{draft(holder).field(StringArgumentType.getString(c,"role"),module.visibleMenu(),IntegerArgumentType.getInteger(c,"slot"),ChocolateFactoryProfile.Source.valueOf(StringArgumentType.getString(c,"source").toUpperCase(Locale.ROOT)),StringArgumentType.getString(c,"prefix"),StringArgumentType.getString(c,"suffix"));out.accept("Exact visible numeric field captured");}))))))))
            .then(literal("delta").then(argument("id",StringArgumentType.word()).then(argument("value",StringArgumentType.word()).then(argument("evidence",StringArgumentType.greedyString()).executes(c->run(c.getSource(),out->{draft(holder).delta(StringArgumentType.getString(c,"id"),decimal(StringArgumentType.getString(c,"value")),StringArgumentType.getString(c,"evidence"),module.visibleMenu());out.accept("Supplied rate assumption recorded for planning only");}))))))
            .then(literal("use").then(argument("scope",StringArgumentType.word()).executes(c->run(c.getSource(),out->{module.useProfile(StringArgumentType.getString(c,"scope"));holder.draft=null;out.accept("Local profile selected; no game profile switch issued");}))))
            .then(literal("save").executes(c->run(c.getSource(),out->{module.captureProfile(draft(holder).build());out.accept("Dated local profile saved from current visible fields; action toggle remains off by default");})))
            .then(literal("plan").then(argument("reserve",StringArgumentType.word()).executes(c->run(c.getSource(),out->{var reserve=decimal(StringArgumentType.getString(c,"reserve"));var p=holder.draft!=null?module.previewPlan(holder.draft.build(),reserve):module.plan(reserve);out.accept("Scope "+p.scope()+"; capacity "+estimate(p.untilCapacity())+"; prestige "+estimate(p.untilPrestige()));for(var u:p.upgrades())out.accept(u.id()+": cost "+u.price()+", affordable "+u.affordable()+", payback "+estimate(u.payback())+"; "+u.assumption());for(var note:p.notes())out.accept(note);var profile=holder.draft!=null?holder.draft.build():module.profile();var o=holder.draft!=null?new McChocolateFactoryPort(c.getSource().getClient()).read(profile):module.inspect();ChocolateFactoryPlanner.collection(profile,o).ifPresent(v->out.accept("Collection "+v.uniqueCollected()+"/"+v.knownTotal()+"; "+v.source()));if(profile.chocobits()!=null)profile.chocobits().read(o.rows()).ifPresent(v->{var upkeep=ChocolateFactoryPlanner.chocobitUpkeep(v.intValueExact());out.accept("Chocobit annual liability "+upkeep.coinsPerSkyBlockYear()+" Coins; due date/funding/payment unknown");});}))))
            .then(literal("goal").then(argument("id",StringArgumentType.word()).then(argument("amount",StringArgumentType.word()).then(argument("reserve",StringArgumentType.word()).executes(c->run(c.getSource(),out->{var comparison=new ChocolateFactoryPlanner().walletGoal(module.profile(),module.inspect(),StringArgumentType.getString(c,"id"),decimal(StringArgumentType.getString(c,"amount")),decimal(StringArgumentType.getString(c,"reserve")));out.accept("Hold: "+estimate(comparison.holding())+"; buy: "+estimate(comparison.buying())+"; "+comparison.assumption());}))))))
            .then(literal("transaction-resource").then(argument("currency",StringArgumentType.word()).then(argument("slot",IntegerArgumentType.integer(0,53)).then(argument("prefix",StringArgumentType.string()).then(argument("suffix",StringArgumentType.string()).executes(c->run(c.getSource(),out->{module.bindTransactionResource(ChocolateSelectedTransactions.Currency.valueOf(StringArgumentType.getString(c,"currency").toUpperCase(Locale.ROOT)),IntegerArgumentType.getInteger(c,"slot"),StringArgumentType.getString(c,"prefix"),StringArgumentType.getString(c,"suffix"));out.accept("Exact independent native funding field bound for this session. Stock/spent/egg counters cannot grant funds; original capture has no funding field");})))))))
            .then(literal("transaction-output").then(argument("inventorySlot",IntegerArgumentType.integer(9,35)).executes(c->run(c.getSource(),out->{module.bindTransactionOutput(IntegerArgumentType.getInteger(c,"inventorySlot"));out.accept("Existing native stack bound for exactly one additional item; no item delivery inferred from a shop counter");}))))
            .then(literal("transaction-select").then(argument("action",StringArgumentType.word()).then(argument("slot",IntegerArgumentType.integer(0,53)).then(argument("budget",StringArgumentType.word()).then(argument("reserve",StringArgumentType.word()).executes(c->run(c.getSource(),out->{if(!module.selectTransaction(ChocolateSelectedTransactions.Action.valueOf(StringArgumentType.getString(c,"action").toUpperCase(Locale.ROOT)),IntegerArgumentType.getInteger(c,"slot"),decimal(StringArgumentType.getString(c,"budget")),decimal(StringArgumentType.getString(c,"reserve"))))throw new IllegalArgumentException("Typed transaction refused: "+module.transactions().reason());out.accept("One native typed transaction selected under cumulative same-scope denomination budget; start through Root guard. Hitman confirmation remains deliberate");})))))))
            .then(literal("transaction-confirm").executes(c->run(c.getSource(),out->{if(!module.confirmTransaction())throw new IllegalArgumentException(module.transactions().reason());out.accept("Explicit retained Hitman quote confirmation selected; waiting for exact native resource and slot result");})))
            .then(literal("transactions").executes(c->run(c.getSource(),out->{var o=module.visibleMenu();if(o==null)throw new IllegalArgumentException("Open native Shop, Hitman or Milestones menu");for(var a:ChocolateSelectedTransactions.Action.values())for(var row:o.rows().values())ChocolateSelectedTransactions.quote(a,o,row.slot()).ifPresent(q->out.accept(q.toString()));out.accept("Faction funding/payment, Chocobit upkeep payment, extra-item shop costs and uncaptured rewards remain unbound. Published upkeep metadata never authorizes payment");})))
            .then(literal("tower-select").executes(c->run(c.getSource(),out->{if(!module.selectTower())throw new IllegalArgumentException(module.diagnostics());out.accept("One exact inactive XV Tower activation selected; start sends one right-click and consumes one observed charge");})))
            .then(literal("prestige-preview").then(argument("maximumObservedWallet",StringArgumentType.word()).executes(c->run(c.getSource(),out->{if(!module.selectPrestigePreview(decimal(StringArgumentType.getString(c,"maximumObservedWallet"))))throw new IllegalArgumentException(module.diagnostics());out.accept("Eligible captured III-to-IV preview selected. Maximum observed wallet applies to this parent snapshot. Start opens preview; reset-all confirmation separately accepts the reset regardless of later accrual");}))))
            .then(literal("prestige-confirm").then(literal("reset-all").executes(c->run(c.getSource(),out->{if(!module.confirmPrestige())throw new IllegalArgumentException("Exact selected III-to-IV preview must be active and unchanged: "+module.diagnostics());out.accept("User explicitly accepted resetting all Chocolate and earned progress for III-to-IV; the preview has no current wallet field. Waiting for native reset result");}))))
            .then(literal("actions").executes(c->run(c.getSource(),out->{for(var j:module.actionJournals())out.accept("Intent "+j.id()+"; local scope "+j.scope()+"; "+j.action()+" "+j.status()+" "+j.phase()+"; "+j.evidence()+"; "+j.result()+"; "+j.reason());out.accept("Scope labels are local capture labels, not persistent account identity. Reconcile only the exact intent after checking the native result");})))
            .then(literal("action-reconcile").then(argument("intent",StringArgumentType.word()).then(argument("result",StringArgumentType.word()).then(argument("original-scope",StringArgumentType.word()).executes(c->run(c.getSource(),out->{var result=StringArgumentType.getString(c,"result");if(!Set.of("applied","not-applied").contains(result))throw new IllegalArgumentException("Use applied or not-applied after checking native result");module.reconcileAction(StringArgumentType.getString(c,"intent"),result.equals("applied"),StringArgumentType.getString(c,"original-scope"));out.accept("Exact consequential intent manually reconciled against a refreshed native inspection and declared original local scope; account identity is unproven. Fresh deliberate selection required");}))))))
            .then(literal("select").then(argument("ids",new ChocolateUpgradeIdsArgument()).then(argument("budget",StringArgumentType.word()).then(argument("reserve",StringArgumentType.word()).executes(c->run(c.getSource(),out->{if(!module.selectUpgrades(List.of(StringArgumentType.getString(c,"ids").split(",",-1)),decimal(StringArgumentType.getString(c,"budget")),decimal(StringArgumentType.getString(c,"reserve"))))throw new IllegalArgumentException(module.diagnostics());out.accept("Inactive exact observed queue selected. Start promptly through standard activation to issue requests");}))))))
            .then(literal("repeat").then(argument("id",StringArgumentType.word()).then(argument("count",IntegerArgumentType.integer(1,16)).then(argument("budget",StringArgumentType.word()).then(argument("reserve",StringArgumentType.word()).then(argument("waitSeconds",IntegerArgumentType.integer(1,300)).executes(c->run(c.getSource(),out->{if(!module.selectRepeatedUpgrade(StringArgumentType.getString(c,"id"),IntegerArgumentType.getInteger(c,"count"),decimal(StringArgumentType.getString(c,"budget")),decimal(StringArgumentType.getString(c,"reserve")),1000L*IntegerArgumentType.getInteger(c,"waitSeconds")))throw new IllegalArgumentException(module.diagnostics());out.accept("Finite employee progression selected. Every future request needs an actual fresh quote, observed funds, cumulative budget/reserve and durable previous ACK; start explicitly");}))))))))
            .then(literal("start").executes(c->run(c.getSource(),out->{if(!guard.start(module))throw new IllegalArgumentException("Standard activation refused; see its local reason");out.accept("Selected queue started");})))
            .then(literal("stop").executes(c->run(c.getSource(),out->{module.stopSelected();out.accept(module.diagnostics());})))
            .then(literal("queues").executes(c->run(c.getSource(),out->{for(var j:module.unresolvedQueueIntents())out.accept("Local queue intent="+j.intentId()+" scope="+j.scope()+" status="+j.status()+" target="+j.upgrade()+" price="+j.price()+"; account identity unproven");})))
            .then(literal("queue-inspect").then(argument("intent",StringArgumentType.word()).then(argument("original-scope",StringArgumentType.word()).then(literal("declare-original-account").executes(c->run(c.getSource(),out->{module.inspectQueueRecovery(StringArgumentType.getString(c,"intent"),StringArgumentType.getString(c,"original-scope"),ChocolateQueueRecovery.DECLARATION);out.accept("You declared this freshly inspected native account corresponds to the retained original scope. Account identity is UNPROVEN; repeat exact intent/scope and declare observed result promptly");}))))))
            .then(literal("reconcile").then(argument("intent",StringArgumentType.word()).then(argument("result",StringArgumentType.word()).then(argument("original-scope",StringArgumentType.word()).then(literal("declare-original-account").executes(c->run(c.getSource(),out->{var result=StringArgumentType.getString(c,"result");if(!Set.of("purchased","not-purchased").contains(result))throw new IllegalArgumentException("Use purchased or not-purchased after checking the native result");module.reconcileQueueRecovery(StringArgumentType.getString(c,"intent"),result.equals("purchased"),StringArgumentType.getString(c,"original-scope"),ChocolateQueueRecovery.DECLARATION);out.accept("Durably recorded explicit human queue declaration; account identity remains UNPROVEN; manual Chocolate debit is separate from native known spend/ACKs; Coin valuation UNKNOWN. Fresh deliberate selection required");}))))))));
    }
    private static ChocolateFactoryDraft draft(Holder h){if(h.draft==null)throw new IllegalArgumentException("Begin a native profile draft first");return h.draft;}
    private static String estimate(ChocolateFactoryPlanner.Estimate e){return e.seconds().map(v->v.stripTrailingZeros().toPlainString()+" seconds").orElse("unknown")+" ("+e.explanation()+")";}
}
